def pick_score_weight_text(top_n=None):
    """Return a '· HR Game% (16%), power (18%), ...' string built from the live
    PICK_SCORE_WEIGHTS, sorted high→low. top_n limits to the biggest N. Used by
    every pick_score help/caption so they never drift from the constant."""
    items = sorted(PICK_SCORE_WEIGHTS.items(), key=lambda kv: kv[1], reverse=True)
    if top_n:
        items = items[:top_n]
    return ", ".join(
        f"{_PICK_SCORE_LABELS.get(k, k)} ({v*100:.0f}%)" for k, v in items
    )


def _calibration_snapshot() -> dict:
    """Return the current calibration constants in the shape that
    save_snapshot expects. Single point of truth — both save call sites
    use this so the snapshot can never lie about what produced the scores.
    """
    return {
        "league_hr_per_pa": LEAGUE_HR_PER_PA,
        "ps_weights": dict(PICK_SCORE_WEIGHTS),
        "ctx_mult_cap": list(CTX_MULT_CAP),
        "split_prior_pa": SPLIT_PRIOR_PA,
        # v45.15 (audit): record the dinger weights + smash thresholds too.
        # When DINGER_BASE_WEIGHTS gets its first evidence-driven reweight (the
        # 15-slate milestone), snapshots must say which weights produced them —
        # otherwise pre/post-reweight slates are indistinguishable when grading.
        "dinger_weights": dict(DINGER_BASE_WEIGHTS),
        "smash_thresholds": {
            "elite_score": SMASH_ELITE_SCORE,
            "strong_score": SMASH_STRONG_SCORE,
            "base_score": SMASH_BASE_SCORE,
            "env_favorable": SMASH_ENV_FAVORABLE,
            "env_neutral": SMASH_ENV_NEUTRAL,
        },
    }


