try:
    from props import hr_prob_full_game
except ImportError:
    def hr_prob_full_game(prob_per_pa, expected_pa=4.2):
        """Fallback: P(>=1 HR in expected_pa) from per-PA prob."""
        if prob_per_pa is None:
            return None
        try:
            return float(1 - (1 - prob_per_pa) ** expected_pa)
        except Exception:
            return None
