            _existing_days = {str(k).split("T")[0] for k in existing}
            for _day in expected_days:
                if _day in _existing_days:
                    covered.add(_day)
            coverage_pct = len(covered) / 14 * 100
            if coverage_pct >= 80:
                st.caption(f"✅ 14-day coverage: {len(covered)}/14 days ({coverage_pct:.0f}%)")
