with st.spinner("Loading slate and stats..."):
    try:
        slate = get_slate(selected_date.isoformat())
        # v45.29 (Pirates PPD): the postponement filter was correctly dropping
        # dead games but doing it SILENTLY — the counter existed in df.attrs
        # yet nothing displayed it. Now the user sees why a game vanished.
        try:
            _ppd_ct = int(slate.attrs.get("dropped_games", 0) or 0)
            if _ppd_ct > 0:
                _ppd_det = slate.attrs.get("dropped_details") or []
                _det_txt = ("  \n" + "  \n".join(f"· {d}" for d in _ppd_det[:6])) if _ppd_det else ""
                st.info(
                    f"ℹ️ **{_ppd_ct} game{'s' if _ppd_ct != 1 else ''} removed "
                    f"from today's slate** (marked as not being played by MLB):"
                    f"{_det_txt}  \n"
                    f"_Delayed and suspended-resumption games are KEPT — only "
                    f"postponed/cancelled games are removed._"
                )
        except Exception:
            pass
    except (ConnectionError, requests.exceptions.RequestException) as _e:
        # MLB Stats API is temporarily unavailable. Show a friendly message
        # and stop instead of letting the raw traceback through.
        st.error(
            f"⚠️ **MLB Stats API is currently unreachable.**\n\n"
            f"This is usually temporary (MLB's servers occasionally overload). "
            f"Try one of:\n"
            f"- Wait 30-60 seconds and refresh the page\n"
            f"- Click '🔄 Force refresh all data' in the sidebar\n"
            f"- Check https://statsapi.mlb.com/api/v1/schedule?sportId=1 in your browser to confirm MLB is back up\n\n"
            f"_Technical detail: {type(_e).__name__}_"
        )
        st.stop()
    except Exception as _e:
        st.error(
            f"⚠️ **Unexpected error loading slate.**\n\n"
            f"Error: {type(_e).__name__}: {_e}\n\n"
            f"Try clicking '🔄 Force refresh all data' in the sidebar."
        )
        st.stop()

if slate.empty:
    st.warning(f"No MLB games found on {selected_date}. Try another date.")
    # v44.95 (user: I can't pattern-analyze or backtest on a gameless day even
    # though those use PAST data). The picks need a slate, but the analysis
    # tools read accumulated snapshot history — so render them here (owner-only)
    # before stopping, instead of killing the whole page on an empty date.
    if owner_mode:
        st.divider()
        st.markdown("### 📊 Off-day tools — analyze past data (no games today)")
        st.caption(
            "There are no games on this date, so there are no picks to show — but "
            "Backtest and Pattern Analysis work off accumulated snapshot history, "
            "so you can still review how past predictions performed and what "
            "patterns the data shows. Handy during the All-Star break or off-days."
        )

        # --- Backtest (history-based, self-contained) ---
        with st.expander("📈 Backtest — projection accuracy vs past outcomes", expanded=True):
            try:
                from backtest import (
                    list_snapshots, load_snapshot,
                    fetch_hitter_outcomes,
                    evaluate_hitter_projections,
                )
                _od_snaps = list_snapshots()
                if not _od_snaps:
                    st.info("No snapshots saved yet — nothing to backtest.")
                else:
                    _od_choice = st.selectbox(
                        "Evaluate snapshot from:", options=_od_snaps,
                        index=len(_od_snaps) - 1, key="_offday_snap_choice",
                    )
                    if st.button("🔍 Evaluate this snapshot", key="_offday_eval_btn"):
                        with st.spinner("Fetching actual outcomes..."):
                            _od_snapshot = load_snapshot(_od_choice)
                            _od_actuals = fetch_hitter_outcomes(_od_choice) if _od_snapshot else {}
                            _od_m = (evaluate_hitter_projections(_od_snapshot, _od_actuals)
                                     if _od_snapshot else {})
                        if _od_m and not _od_m.get("error"):
                            c1, c2, c3, c4 = st.columns(4)
                            c1.metric("Hitters tracked", _od_m.get("hitters_who_played", 0))
                            c2.metric("Total HRs", _od_m.get("total_actual_hrs", 0))
                            c3.metric("Slate HR rate", f"{_od_m.get('actual_hr_rate_pct', 0)}%")
                            c4.metric("Top-10 hit rate", f"{_od_m.get('top10_hr_hit_rate', 0)}%")
                            _od_lines = [
                                f"📈 BACKTEST — {_od_choice}",
                                f"Hitters tracked: {_od_m.get('hitters_who_played', 0)} · "
                                f"Total HRs: {_od_m.get('total_actual_hrs', 0)} · "
                                f"Slate HR rate: {_od_m.get('actual_hr_rate_pct', 0)}% · "
                                f"Top-10 hit rate: {_od_m.get('top10_hr_hit_rate', 0)}%",
                            ]
                            _od_br = _od_m.get("brier_score")
                            if _od_br is not None:
                                _od_lines.append(f"Brier: {_od_br:.4f}")
                            st.session_state["_backtest_copy_text"] = "\n".join(_od_lines)
                            st.session_state["_backtest_copy_label"] = _od_choice
                        else:
                            st.warning("No matched outcomes for that snapshot yet.")
                    # durable copy toggle (survives reruns)
                    _od_copy = st.session_state.get("_backtest_copy_text")
                    if _od_copy:
                        if st.checkbox("📋 Show copyable backtest text",
                                       key="_offday_bt_copy"):
                            st.code(_od_copy, language=None)
            except Exception as _od_e:
                st.error(f"Off-day backtest error: {type(_od_e).__name__}: {_od_e}")

        # --- Pattern discovery (history-based) ---
        with st.expander("🔬 Pattern Analysis — run on accumulated history", expanded=True):
            st.caption(
                "Runs the correlation/pattern discovery over all banked "
                "snapshot+outcome pairings and refreshes the learning history."
            )
            if st.button("🔬 Run pattern discovery now", key="_offday_pattern_btn"):
                try:
                    from backtest import auto_run_pattern_discovery
                    with st.spinner("Analyzing accumulated snapshots..."):
                        _od_pd = auto_run_pattern_discovery()
                    st.success(_od_pd.get("note", "Pattern discovery complete."))
                    st.session_state["_offday_pattern_note"] = _od_pd.get("note", "")
                except Exception as _od_pe:
                    st.error(f"Pattern discovery error: {type(_od_pe).__name__}: {_od_pe}")
            _od_pn = st.session_state.get("_offday_pattern_note")
            if _od_pn:
                if st.checkbox("📋 Show copyable pattern-discovery note",
                               key="_offday_pd_copy"):
                    st.code(_od_pn, language=None)
            st.info(
                "The full Pattern Analysis tables (feature importance, cohorts, "
                "Proposed Weights) render on a normal game-day. This off-day view "
                "runs the discovery + refreshes history; open the app on a game-day "
                "for the complete breakdown."
            )
    st.stop()

# ============================================================================
# FILTER: hide games that are already in progress or final
# ============================================================================
# When user is checking the slate mid-day, the 1pm games are already started
# and the data is no longer actionable for HR props. Only show upcoming games.
#
# This filter is BET-ORIENTED — it strips games where you can no longer place
# a bet. If you're reviewing the day's results or studying which players
# homered (useful for next-day adjustment), uncheck this to see started/final
# games and their lineup data.
hide_started = st.sidebar.checkbox(
    "Hide games already started/final (bet-oriented view)",
    value=True,
    help=(
        "BET MODE (checked): Removes games whose first pitch was before 'now'. "
        "Use when you're picking plays for tonight.\n\n"
        "REVIEW MODE (unchecked): Shows every game on the schedule including "
        "in-progress and final ones. Use when reviewing how the day played out, "
        "auditing model performance, or studying which players homered in "
        "afternoon games."
    ),
)

# v43.17 (user-requested): Bat tracking / Blast % — OPT-IN. Defaults OFF
# because Savant's bat tracking endpoints have changed field names between
# 2024 beta and 2025 production, and we'd rather YOU see whether the fetch
# worked (via the status caption below) than silently blend missing data
# into hr_form. When enabled, blast_pct is fetched, merged into
# hitter_stats, and added to the hr_form composite at a small weight (0.05)
# so it can lift hitters with elite swing quality without overpowering
# season-long power signals like barrel%.
use_bat_tracking = st.sidebar.checkbox(
    "📡 Fetch bat tracking (Blast % + IAA)",
    value=True,  # v43.54: default True so IAA-driven HR Criteria #4 actually
                  # populates. Previously False — meant ideal_attack_angle_pct
                  # was empty for every hitter on every default-config slate,
                  # making criterion 4 permanently '·' (unmet) and silently
                  # degrading the HR Profile checklist. Bat tracking has been
                  # in Savant for 18+ months — field-name drift concern is
                  # much lower than it was when the opt-in default was set.
    help=(
        "Statcast bat-tracking data. Two fields used downstream:\n"
        "  • blast_pct — swing that's squared-up AND fast (≥75 mph bat speed). "
        "Gets a small (0.05) weight in hr_form.\n"
        "  • ideal_attack_angle_pct (IAA) — % of swings on the ideal launch "
        "angle for the pitch type. This is HR Criteria #4 in the HR Profile "
        "checklist.\n\n"
        "TURN OFF to skip the fetch (slightly faster page load). When off, "
        "HR Criteria #4 will be '·' for every hitter (no IAA data), and "
        "hr_form falls back to v43.16 weights (no blast component). "
        "No silent degradation — the status caption shows what happened.\n\n"
        "Savant has changed field names before — if the fetch returns empty, "
        "the status caption goes ❌ and the features above gracefully turn off."
    ),
)
if hide_started and selected_date == _today_et():  # v44.97: ET-aware
    try:
        # v43.43 (reviewer-validated bias fix): the snapshot payload records
        # which games were dropped via dropped_gamepks / n_filtered (set
        # later in the bias metadata block). We previously stashed a full
        # slate.copy() here under the name `slate_unfiltered`, but it was
        # never actually read — v43.64 removed the dead variable. If a
        # future feature needs the full pre-filter frame for diff/audit,
        # add it back at that point.
        # v42r: use Timestamp.now(tz="UTC") instead of utcnow().tz_localize().
        # On older pandas versions utcnow() returns naive UTC and then
        # tz_localize behaves correctly, but on newer pandas utcnow() returns
        # tz-aware (deprecation) and tz_localize raises. The .now(tz=...) form
        # is the safe, forward-compatible idiom.
        now_utc = pd.Timestamp.now(tz="UTC")
        if "gameTime" in slate.columns:
            def _is_upcoming(t):
                if pd.isna(t):
                    return True  # if no time, default to showing
                try:
                    if hasattr(t, "tzinfo") and t.tzinfo is not None:
                        return t > now_utc
                    # v44.12 (user bug: 6:40pm ET game showed "locked" before
                    # 3pm): a NAIVE gameTime is almost certainly MLB local
                    # (US Eastern), NOT UTC. Assuming UTC shifted a 22:40 ET
                    # first pitch to 22:40 UTC = 6:40pm *UTC* = 2:40pm ET,
                    # making evening games look already-started at midday.
                    # Localize naive times to US/Eastern before comparing.
                    try:
                        _t_et = pd.Timestamp(t).tz_localize(
                            "US/Eastern", ambiguous=True, nonexistent="shift_forward"
                        )
                        return _t_et.tz_convert("UTC") > now_utc
                    except Exception:
                        # last-resort: assume UTC (old behavior)
                        return pd.Timestamp(t).tz_localize("UTC") > now_utc
                except Exception:
                    return True
            mask = slate["gameTime"].apply(_is_upcoming)
            n_filtered = (~mask).sum()
            # v43.43: capture which games were filtered, for snapshot metadata
            try:
                dropped_gamepks = (
                    slate.loc[~mask, "gamePk"].astype(int).tolist()
                    if "gamePk" in slate.columns else []
                )
            except Exception:
                dropped_gamepks = []
            slate = slate[mask].reset_index(drop=True)
            # Stash for snapshot bias warning downstream
            st.session_state["_filter_dropped_games"] = int(n_filtered)
            st.session_state["_filter_dropped_gamepks"] = dropped_gamepks
            if n_filtered > 0:
                st.info(
                    f"⏱️ Hiding {n_filtered} game{'s' if n_filtered != 1 else ''} "
                    f"that already started. Uncheck 'Hide games already started/final' "
                    f"in sidebar to see them."
                )
        else:
            st.session_state["_filter_dropped_games"] = 0
    except Exception:
        # If filtering fails for any reason, don't block the user — show everything
        pass

if slate.empty:
    st.warning(
        f"All games on {selected_date} have started or finished. "
        f"Uncheck 'Hide games already started/final' in sidebar to see them."
    )
    st.stop()

# Statcast pulls — wrap with try/except so transient timeouts don't crash app
try:
    hitter_stats = get_hitter_stats(stats_day=_stats_day_key()) if not slate.empty else pd.DataFrame()
    # v45.14 (review P1 #3): normalize player_id dtype ONCE at the source.
    # Several downstream merges (zone tiers, hand statcast, bat tracking,
    # sprint) use raw .merge — if the fetcher ever returns object/float ids,
    # those joins would silently yield all-NaN. Int64 here kills that class.
    if hitter_stats is not None and not hitter_stats.empty and "player_id" in hitter_stats.columns:
        hitter_stats["player_id"] = pd.to_numeric(
            hitter_stats["player_id"], errors="coerce").astype("Int64")

    # v44.31: pinpoint diagnostic to isolate WHERE distance data is lost.
    # The fetch trace shows dist_merged=251 inside get_hitter_stats, but
    # combined_picks shows 0% — so either (a) the column doesn't survive the
    # build_matchup_table join, or (b) the 251 merged onto non-slate players.
    # This logs coverage in hitter_stats ITSELF (the source), so if it's high
    # here but 0% in combined_picks, the loss is the downstream join — and if
    # it's already low here, the merge assigned to the wrong IDs.
    try:
        if not hitter_stats.empty:
            _hs_n = len(hitter_stats)
            _ad = int(hitter_stats.get("avg_dist", pd.Series(dtype=float)).notna().sum()) if "avg_dist" in hitter_stats.columns else -1
            _ahd = int(hitter_stats.get("avg_hr_distance", pd.Series(dtype=float)).notna().sum()) if "avg_hr_distance" in hitter_stats.columns else -1
            _bc = int(hitter_stats.get("barrel_count", pd.Series(dtype=float)).notna().sum()) if "barrel_count" in hitter_stats.columns else -1
            # v44.33: dtype of player_id + a sample of the IDs that HAVE avg_dist,
            # so we can see if it's an ID-type or ID-space mismatch downstream.
            _pid_dtype = str(hitter_stats["player_id"].dtype) if "player_id" in hitter_stats.columns else "no-col"
            _ad_ids = []
            if "avg_dist" in hitter_stats.columns and "player_id" in hitter_stats.columns:
                _ad_ids = hitter_stats[hitter_stats["avg_dist"].notna()]["player_id"].head(5).tolist()
            stash_diagnostic(
                "pipeline_health",
                f"🔬 hitter_stats source coverage (of {_hs_n} hitters): "
                f"avg_dist={_ad if _ad>=0 else 'col-missing'}, "
                f"avg_hr_distance={_ahd if _ahd>=0 else 'col-missing'}, "
                f"barrel_count={_bc if _bc>=0 else 'col-missing'}  "
                f"| pid_dtype={_pid_dtype}, sample_ids_with_dist={_ad_ids}  "
                f"← if high here but 0% in combined_picks, loss is the matchup join",
                level="info",
            )
    except Exception:
        pass

    # v43.76: removed the [Trace] hitter_stats coverage diagnostic that
    # was added in v43.71 to debug the avg_dist merge. The investigation
    # was closed in v43.75 (avg_dist dropped from Nuclear). Diagnostic
    # was producing noise without actionable signal.
except (ConnectionError, requests.exceptions.RequestException) as _e:
    st.error(
        f"⚠️ **Baseball Savant (hitter data) is currently unreachable.**\n\n"
        f"This is usually temporary. Try:\n"
        f"- Wait 30-60 seconds and refresh\n"
        f"- Click '🔄 Force refresh all data' in the sidebar\n\n"
        f"_Error: {type(_e).__name__}_"
    )
    st.stop()

try:
    pitcher_stats = get_pitcher_stats(stats_day=_stats_day_key()) if not slate.empty else pd.DataFrame()
    # v45.14 (review P1 #3): same source-level Int64 normalization as hitters.
    if pitcher_stats is not None and not pitcher_stats.empty and "player_id" in pitcher_stats.columns:
        pitcher_stats["player_id"] = pd.to_numeric(
            pitcher_stats["player_id"], errors="coerce").astype("Int64")
except (ConnectionError, requests.exceptions.RequestException) as _e:
    st.error(
        f"⚠️ **Baseball Savant (pitcher data) is currently unreachable.**\n\n"
        f"_Error: {type(_e).__name__}_"
    )
    st.stop()

try:
    pitcher_arsenal_all = get_pitcher_arsenal() if not slate.empty else pd.DataFrame()
except Exception:
    # Arsenal is non-critical; fall back to empty
    pitcher_arsenal_all = pd.DataFrame()

# v43 EXPERIMENTAL: Zone tier fetchers (Savant heart/shadow/chase/waste).
# Could not validate endpoints from dev env — these are best-effort. Empty
# DataFrame on failure means the zone_fit_flag will be empty for everyone
# (plate_discipline_flag remains as the primary working zone signal).
try:
    from data_fetcher import get_pitcher_zone_tiers, get_hitter_zone_tiers
    pitcher_zone_tiers = get_pitcher_zone_tiers(stats_day=_stats_day_key()) if not slate.empty else pd.DataFrame()
    hitter_zone_tiers = get_hitter_zone_tiers(stats_day=_stats_day_key()) if not slate.empty else pd.DataFrame()
    _zone_fetch_status = (
        "✅ working" if (not pitcher_zone_tiers.empty and not hitter_zone_tiers.empty)
        else "⚠️ partial" if (not pitcher_zone_tiers.empty or not hitter_zone_tiers.empty)
        else "❌ unavailable (plate_discipline_flag still active)"
    )
except Exception as _zone_err:
    pitcher_zone_tiers = pd.DataFrame()
    hitter_zone_tiers = pd.DataFrame()
    _zone_fetch_status = f"❌ error: {type(_zone_err).__name__}"

# Merge zone tier data into hitter_stats and pitcher_stats if available
if not pitcher_zone_tiers.empty and "player_id" in pitcher_stats.columns:
    pitcher_stats = pitcher_stats.merge(
        pitcher_zone_tiers, on="player_id", how="left", suffixes=("", "_zt"),
    )
    # v45.10 (review): drop orphaned _zt collision columns (keep the original).
    _zt_dupes = [c for c in pitcher_stats.columns
                 if c.endswith("_zt") and c[:-3] in pitcher_stats.columns]
    if _zt_dupes:
        pitcher_stats = pitcher_stats.drop(columns=_zt_dupes)
if not hitter_zone_tiers.empty and "player_id" in hitter_stats.columns:
    hitter_stats = hitter_stats.merge(
        hitter_zone_tiers, on="player_id", how="left", suffixes=("", "_zt"),
    )
    _zt_dupes = [c for c in hitter_stats.columns
                 if c.endswith("_zt") and c[:-3] in hitter_stats.columns]
    if _zt_dupes:
        hitter_stats = hitter_stats.drop(columns=_zt_dupes)

# ----------------------------------------------------------------------------
# v43.5: SAVANT HANDEDNESS STATCAST (experimental)
# ----------------------------------------------------------------------------
# Closes the most important model gap: power_score / hr_form / grade use
# season-overall barrel%, hard_hit%, xwOBA, EV — NOT handedness-specific
# contact quality. So a hitter who's bad vs one side (or great vs one side)
# but average overall gets the wrong grade in that matchup.
#
# Same defensive pattern as zone tiers: try multiple Savant URL formats,
# return empty DataFrame on failure. Caption status indicator shows live
# health. On success, columns vs_lhp_barrel_pct / vs_rhp_barrel_pct etc.
# get merged into hitter_stats, and the per-game override is applied right
# before power_score/hr_form compute (so they "see" tonight's effective
# values without code changes inside those functions).
try:
    from data_fetcher import get_hitter_handedness_statcast
    hitter_hand_statcast = (
        get_hitter_handedness_statcast(stats_day=_stats_day_key())
        if not slate.empty else pd.DataFrame()
    )
    if hitter_hand_statcast.empty:
        _hand_statcast_status = "❌ unavailable (using season-overall)"
    else:
        # Count how many hitters have either side populated as a quality signal
        _l_count = 0
        _r_count = 0
        if "vs_lhp_barrel_pct" in hitter_hand_statcast.columns:
            _l_count = hitter_hand_statcast["vs_lhp_barrel_pct"].notna().sum()
        if "vs_rhp_barrel_pct" in hitter_hand_statcast.columns:
            _r_count = hitter_hand_statcast["vs_rhp_barrel_pct"].notna().sum()
        if _l_count > 0 and _r_count > 0:
            _hand_statcast_status = f"✅ working ({_l_count} LHP, {_r_count} RHP)"
        elif _l_count > 0 or _r_count > 0:
            _hand_statcast_status = f"⚠️ partial ({_l_count} LHP, {_r_count} RHP)"
        else:
            _hand_statcast_status = "❌ empty (using season-overall)"
except Exception as _hsc_err:
    hitter_hand_statcast = pd.DataFrame()
    _hand_statcast_status = f"❌ error: {type(_hsc_err).__name__}"

# Merge into hitter_stats so the vs_lhp_* / vs_rhp_* columns are available
# to apply_handedness_overrides per-game.
if not hitter_hand_statcast.empty and "player_id" in hitter_stats.columns:
    # Suffix collisions are unlikely (these are new columns) but use suffix
    # safety for robustness.
    hitter_stats = hitter_stats.merge(
        hitter_hand_statcast, on="player_id", how="left",
        suffixes=("", "_hs"),
    )
    # v45.10 (review): drop orphaned _hs collision columns (keep the original).
    _hs_dupes = [c for c in hitter_stats.columns
                 if c.endswith("_hs") and c[:-3] in hitter_stats.columns]
    if _hs_dupes:
        hitter_stats = hitter_stats.drop(columns=_hs_dupes)

# v43.17 (user-requested): Bat tracking / Blast % — OPT-IN.
# Fetches Statcast bat tracking only if the sidebar toggle is enabled.
# Status caption shows the live result so user can SEE if Savant's
# schema has drifted (caption goes ❌). When ❌, hr_form falls back to
# v43.16 weights without blast_pct — no silent degradation.
_bat_tracking_status = "⏸️ disabled (toggle in sidebar to enable)"
if use_bat_tracking:
    try:
        # v45.33: Sweet Spot % — tracked-only enrichment (isolated fetch,
        # fill-if-missing merge, zero scoring impact). Feeds Section G so the
        # evidence is already banked when post-reweight experiments begin.
        try:
            from data_fetcher import get_hitter_sweet_spot
            if not slate.empty:
                _ss_df = get_hitter_sweet_spot(
                    season=selected_date.year, stats_day=_stats_day_key())
                if (_ss_df is not None and not _ss_df.empty
                        and "player_id" in hitter_stats.columns):
                    hitter_stats = merge_on_player_id(
                        hitter_stats, _ss_df, cols=["sweet_spot_pct"],
                        overwrite=False)
        except Exception as _ss_e:
            log_swallowed_error("sweet_spot_fetch", _ss_e, surface=False)

        from data_fetcher import get_bat_tracking
        # v43.62 (reviewer-validated): get_bat_tracking now returns a 3-tuple
        # (df, status, savant_cols). The savant_cols list survives @st.cache_data
        # (the global it used to write to didn't). Stash to session_state so
        # the IAA diagnostic in Pipeline Health sees fresh data on cache hits.
        if not slate.empty:
            bat_track_df, _bat_tracking_status, _savant_cols = get_bat_tracking(
                season=selected_date.year, stats_day=_stats_day_key()
            )
        else:
            bat_track_df, _bat_tracking_status, _savant_cols = (
                pd.DataFrame(), "⏸️ no slate", []
            )
        # Surface the column list where last_bat_tracking_columns() can read it
        st.session_state["_last_bat_tracking_cols"] = _savant_cols
        if not bat_track_df.empty and "player_id" in hitter_stats.columns:
            # v43.18 (reviewer-validated, blast asymmetry fix):
            # _score_from_weights renormalizes over present columns. So a
            # hitter WITH blast_pct gets their other 8 components implicitly
            # down-weighted, while a hitter WITHOUT blast_pct doesn't —
            # asymmetric scoring on the same composite. The reviewer's
            # exact phrasing: "missing-blast hitters get a slight relative
            # boost on their remaining components." Fix: impute the slate
            # MEDIAN of populated blast_pct for missing rows. That way
            # every hitter has the column, the weighted average comparison
            # is fair, and the missing-data hitters are treated as
            # "average swing quality" rather than "scored on a different
            # denominator."
            _keep_cols = ["player_id", "blast_pct"]
            # v43.51 (reviewer-validated): explicitly include ideal_attack_angle_pct
            # so it survives the merge into hitter_stats. Previously the loop
            # below only added bat_speed/fast_swing/squared_up, so IAA was
            # dropped here even when get_bat_tracking found it — making the
            # v43.42 diagnostic blame Savant schema drift when the real bug
            # was app-side filtering.
            for _c in ("bat_speed", "fast_swing_pct", "squared_up_pct",
                        "ideal_attack_angle_pct"):
                if _c in bat_track_df.columns:
                    _keep_cols.append(_c)
            hitter_stats = hitter_stats.merge(
                bat_track_df[_keep_cols], on="player_id", how="left",
                suffixes=("", "_bt"),
            )
            # Compute median of populated values, impute into NaN rows
            try:
                # v44.63 (user: make sure imputed values don't skew a player's
                # individual data or the correlations). PRESERVE the real,
                # un-imputed blast_pct in a parallel column FIRST. The imputed
                # version is used for the display composite (so a missing-data
                # hitter isn't scored on a different denominator — the reviewer's
                # fairness fix), but the REAL-only column is what gets snapshotted
                # and graded, so 380 fabricated identical medians can't dilute
                # the blast_pct correlation or drag an elite hitter's graded
                # profile toward the mean.
                hitter_stats["blast_pct_real"] = hitter_stats["blast_pct"]
                _bp_median = float(hitter_stats["blast_pct"].dropna().median())
                if not pd.isna(_bp_median):
                    _na_count = int(hitter_stats["blast_pct"].isna().sum())
                    hitter_stats["blast_pct"] = hitter_stats["blast_pct"].fillna(_bp_median)
                    # mark which rows were imputed so downstream can flag them
                    hitter_stats["blast_pct_imputed"] = hitter_stats["blast_pct_real"].isna()
                    _bat_tracking_status += f" (median-imputed {_na_count})"
            except Exception:
                pass
    except Exception as _bt_err:
        _bat_tracking_status = f"❌ error: {type(_bt_err).__name__}"

# v43.56: stash bat tracking outcome to Pipeline Health so the user can see
# fetch result alongside the ALWAYS_EXPECTED_COLUMNS warning. Without this,
# when IAA is missing but the toggle is ON, the assertion says "turn it on"
# (misleading) and there's no signal about WHY the data isn't flowing. Now
# the status appears in pipeline_health, with context:
#   ✅ N hitters         = fetcher succeeded and merged
#   ❌ error / no rows   = fetcher returned empty (Savant schema drift / API)
#   ⏸️ disabled          = toggle is off
try:
    _bt_msg = f"**Bat tracking fetch:** `{_bat_tracking_status}`"
    if "✅" in str(_bat_tracking_status):
        _bt_msg += "  ← if HR Criteria #4 still '·' for everyone, IAA field wasn't returned (see below)"
    elif "❌" in str(_bat_tracking_status):
        _bt_msg += (
            "  ← fetcher failed. IAA + blast_pct will both be missing. "
            "Check the IAA column-list diagnostic if it appears below."
        )
    elif "⏸️" in str(_bat_tracking_status):
        _bt_msg += "  ← toggle is off. HR Criteria #4 will be '·' for everyone."
    stash_diagnostic("pipeline_health", _bt_msg)
except Exception:
    pass

# HAND-SPLIT ARSENALS (June 2026)
# Pitchers throw very different pitch mixes vs LHB vs RHB. A RHP might throw
# 38% sliders to RHB but only 12% sliders to LHB (slider moves same-side away;
# changeup runs opposite-side away). Without these splits, projections use the
# pitcher's overall mix which dramatically misrepresents what a hitter will
# actually see in a same-side or opposite-side matchup.
try:
    from data_fetcher import get_pitcher_arsenal_vs_hand
    pitcher_arsenal_vs_L = get_pitcher_arsenal_vs_hand(batter_hand="L") if not slate.empty else pd.DataFrame()
    pitcher_arsenal_vs_R = get_pitcher_arsenal_vs_hand(batter_hand="R") if not slate.empty else pd.DataFrame()
except Exception:
    pitcher_arsenal_vs_L = pd.DataFrame()
    pitcher_arsenal_vs_R = pd.DataFrame()

# Pitcher handedness splits (vs LHB / vs RHB)
# Use MLB Stats API statSplits which IS documented and works on Streamlit Cloud.
# We only fetch splits for pitchers in TODAY'S slate (typically 26-30 pitchers)
# instead of every pitcher in the league.
# v45.14 (review P1 #9): slate_pitcher_ids is pure slate parsing — hoisted OUT
# of the splits try-block so a splits-import failure no longer silently kills
# the day/night + IL block that also needs these ids (the old coupling was
# papered over by an `except NameError` downstream).
slate_pitcher_ids = []
for col in ["away_pitcher_id", "home_pitcher_id"]:
    if col in slate.columns:
        for pid in slate[col].dropna().unique():
            try:
                slate_pitcher_ids.append(int(pid))
            except (TypeError, ValueError):
                continue
slate_pitcher_ids = tuple(set(slate_pitcher_ids))

try:
    from data_fetcher import get_pitcher_handedness_splits
    pitcher_splits = get_pitcher_handedness_splits(pitcher_ids=slate_pitcher_ids) if slate_pitcher_ids else pd.DataFrame()
    if (pitcher_splits is not None and not pitcher_splits.empty
            and "player_id" in pitcher_stats.columns):
        # v45.11: canonical player_id merge (Int64-normalize + drop collisions).
        pitcher_stats = merge_on_player_id(pitcher_stats, pitcher_splits)
except Exception:
    # Don't block app if MLB Stats API splits fetch fails
    pass

# HITTER vs-LHP/vs-RHP splits — biggest accuracy gap closed (June 2026).
# Without these, a hitter's overall season barrel% gets used for ALL matchups,
# missing reverse-platoon guys like Adell (overall 8.8% barrel, vs-LHP 31.6%).
# We fetch for slate-relevant hitters only to keep API load manageable.
try:
    from data_fetcher import get_hitter_handedness_splits, get_team_roster
    # Collect all hitter IDs from team rosters of slate games (~200-300 IDs)
    hitter_ids_set = set()
    for col in ("away_team_id", "home_team_id"):
        if col not in slate.columns:
            continue
        for tid in slate[col].dropna().unique():
            try:
                roster = get_team_roster(int(tid))
                for p in roster:
                    pid = p.get("id")
                    if pid:
                        hitter_ids_set.add(int(pid))
            except Exception:
                continue
    hitter_ids_tuple = tuple(sorted(hitter_ids_set))
    if hitter_ids_tuple:
        with st.spinner(f"Fetching vs-LHP/vs-RHP splits for {len(hitter_ids_tuple)} hitters (cached 1hr)..."):
            hitter_splits = get_hitter_handedness_splits(hitter_ids=hitter_ids_tuple)
        if (hitter_splits is not None and not hitter_splits.empty
                and "player_id" in hitter_stats.columns):
            # v45.11: canonical player_id merge.
            hitter_stats = merge_on_player_id(hitter_stats, hitter_splits)
            # Diagnostic: track how many hitters got splits
            n_with_lhp_splits = hitter_stats.get("vs_lhp_pa", pd.Series(dtype=float)).notna().sum()
            n_with_rhp_splits = hitter_stats.get("vs_rhp_pa", pd.Series(dtype=float)).notna().sum()
            st.session_state["_hitter_splits_count"] = (
                f"{n_with_lhp_splits} vs-LHP, {n_with_rhp_splits} vs-RHP "
                f"(of {len(hitter_stats)} total hitters)"
            )
except Exception as _e:
    st.session_state["_hitter_splits_err"] = str(_e)[:200]

# HR PROFILE (June 2026): avg HR distance + max exit velo per hitter.
# Adds hr_profile (categorical) and hr_profile_label (display) columns.
# Lets users see "moonshot vs laser" so they can factor park dimensions
# and wind effects appropriately.
try:
    from data_fetcher import get_hitter_hr_profile
    hr_profile = get_hitter_hr_profile()
    if (hr_profile is not None and not hr_profile.empty
            and "player_id" in hitter_stats.columns):
        # v45.11: canonical player_id merge.
        hitter_stats = merge_on_player_id(hitter_stats, hr_profile)
except Exception as _e:
    st.session_state["_hr_profile_err"] = str(_e)[:200]

# NEW: Pitcher day/night splits + IL status
# Only fetch for slate pitchers (~26-30 calls each)
_pitcher_dn_il_err = None
try:
    from data_fetcher import get_pitcher_day_night_splits, get_pitchers_il_status
    if slate_pitcher_ids:
        pitcher_dn = get_pitcher_day_night_splits(pitcher_ids=slate_pitcher_ids)
        if pitcher_dn is not None and not pitcher_dn.empty and "player_id" in pitcher_stats.columns:
            # v45.11: canonical player_id merge.
            pitcher_stats = merge_on_player_id(pitcher_stats, pitcher_dn)
        # IL status
        pitcher_il = get_pitchers_il_status(slate_pitcher_ids)
        if pitcher_il is not None and not pitcher_il.empty and "player_id" in pitcher_stats.columns:
            # v45.11: canonical player_id merge.
            pitcher_stats = merge_on_player_id(pitcher_stats, pitcher_il)
except NameError as _e:
    # slate_pitcher_ids not defined - handedness fetch failed earlier
    _pitcher_dn_il_err = f"NameError: {_e}"
except Exception as _e:
    _pitcher_dn_il_err = f"{type(_e).__name__}: {_e}"

# Surface the error in a small caption so we can debug
if _pitcher_dn_il_err:
    with st.sidebar:
        st.caption(f"⚠️ Day/Night+IL fetch issue: {_pitcher_dn_il_err}")

# Traditional stats
hitter_trad = get_hitter_traditional(stats_day=_stats_day_key()) if not slate.empty else pd.DataFrame()
pitcher_trad = get_pitcher_traditional(stats_day=_stats_day_key()) if not slate.empty else pd.DataFrame()

# Merge traditional stats - force player_id types to match
# CRITICAL: use combine_first style merge so we never overwrite Savant values
# with trad-API NaN. Only fill in where Savant data is missing.
if not hitter_trad.empty and "player_id" in hitter_stats.columns:
    hitter_stats["player_id"] = pd.to_numeric(hitter_stats["player_id"], errors="coerce").astype("Int64")
    hitter_trad["player_id"] = pd.to_numeric(hitter_trad["player_id"], errors="coerce").astype("Int64")
    drop = [c for c in ["player_name"] if c in hitter_trad.columns]
    # Use _trad suffix and then manually coalesce afterward
    hitter_stats = hitter_stats.merge(
        hitter_trad.drop(columns=drop, errors="ignore"),
        on="player_id", how="left", suffixes=("", "_trad"),
    )
    # Coalesce: keep Savant value, fall back to trad if Savant is NaN.
    # NOTE (v45.08): this is the OPPOSITE precedence from the pitcher block below
    # (which prefers trad) — INTENTIONAL, not a copy-paste error. For hitters,
    # Savant computes these rate/count stats well; for pitchers, official
    # ERA/WHIP/IP from MLB Stats API are ground truth over Savant estimates.
    for col in ["obp", "slg", "ops", "avg", "home_run", "rbi", "runs", "sb"]:
        trad_col = f"{col}_trad"
        if trad_col in hitter_stats.columns:
            if col in hitter_stats.columns:
                hitter_stats[col] = hitter_stats[col].fillna(hitter_stats[trad_col])
            else:
                hitter_stats[col] = hitter_stats[trad_col]
            hitter_stats = hitter_stats.drop(columns=[trad_col])

if not pitcher_trad.empty and "player_id" in pitcher_stats.columns:
    pitcher_stats["player_id"] = pd.to_numeric(pitcher_stats["player_id"], errors="coerce").astype("Int64")
    pitcher_trad["player_id"] = pd.to_numeric(pitcher_trad["player_id"], errors="coerce").astype("Int64")
    drop = [c for c in ["player_name"] if c in pitcher_trad.columns]
    pitcher_stats = pitcher_stats.merge(
        pitcher_trad.drop(columns=drop, errors="ignore"),
        on="player_id", how="left", suffixes=("", "_trad"),
    )
    # Coalesce era, whip, ip, hr9, k9, bb9 — PREFER trad (real MLB Stats API)
    # over Savant-derived estimates. This was a real bug: Savant unconditionally
    # set k9 = k_percent * 4.3 * 9 / 100, so the trad fillna() never fired.
    # Now trad wins where it exists, Savant-derived fills NaN.
    for col in ["era", "whip", "ip", "hr9", "k9", "bb9"]:
        trad_col = f"{col}_trad"
        if trad_col in pitcher_stats.columns:
            if col in pitcher_stats.columns:
                # Trad first, Savant-derived as fallback for NaN positions
                pitcher_stats[col] = pitcher_stats[trad_col].fillna(pitcher_stats[col])
            else:
                pitcher_stats[col] = pitcher_stats[trad_col]
            pitcher_stats = pitcher_stats.drop(columns=[trad_col])

# If OBP/SLG still missing after both sources, derive from Statcast components.
# v43.18 (reviewer-validated): the previous guard `.isna().all()` only fired
# when EVERY row was NaN. After the trad coalesce, SLG is PARTIALLY populated
# (some from Statcast, some from MLB Stats traditional, some still missing),
# so .all() returns False and the rows that ARE still NaN never got derived.
# Same bug class as the v42x LA-fill fix. Mask-fill: derive only the rows
# that are actually NaN, leave good values intact.
if "slg" in hitter_stats.columns and hitter_stats["slg"].isna().any():
    if "iso" in hitter_stats.columns and "avg" in hitter_stats.columns:
        _mask = hitter_stats["slg"].isna()
        _derived = (hitter_stats["iso"] + hitter_stats["avg"]).round(3)
        hitter_stats.loc[_mask, "slg"] = _derived[_mask]

# Backstop: derive ISO from SLG - AVG for rows still missing it.
# v43.18: same mask-fill pattern. Was `.isna().all()` which only fired
# when ZERO hitters had ISO from Statcast — a single populated row
# suppressed derivation for everyone else.
if "iso" in hitter_stats.columns and hitter_stats["iso"].isna().any():
    if "slg" in hitter_stats.columns and "avg" in hitter_stats.columns:
        _mask = hitter_stats["iso"].isna()
        _derived = (hitter_stats["slg"] - hitter_stats["avg"]).round(3)
        # ISO can't be negative — clamp at 0 (handles tiny-sample AVG>SLG)
        hitter_stats.loc[_mask, "iso"] = _derived[_mask].clip(lower=0)
elif "iso" not in hitter_stats.columns:
    if "slg" in hitter_stats.columns and "avg" in hitter_stats.columns:
        hitter_stats["iso"] = (
            (hitter_stats["slg"] - hitter_stats["avg"]).round(3).clip(lower=0)
        )

# Per-pitcher fallback: fetch stats individually for any starter still missing data
with st.spinner("Filling in missing pitcher data..."):
    try:
        pitcher_stats = fill_pitcher_stats_for_slate(pitcher_stats, slate)
    except Exception as e:
        st.warning(f"Per-pitcher fill skipped: {e}")

# Per-hitter launch angle fill: pulls REAL LA from Statcast search for any
# hitter on today's slate missing it. Cached 24h per player so the cost is
# only paid once per day.
if not hitter_stats.empty:
    # Trigger LA fill if >30% of hitters are missing LA. Previously we only
    # triggered on 100% missing, which meant a single hitter with LA from a
    # different source would suppress the fill for everyone else.
    if "launch_angle" not in hitter_stats.columns:
        needs_la = True
        la_missing_pct_before = 100.0
        la_n_total_before = len(hitter_stats)
    else:
        la_n_total_before = len(hitter_stats)
        la_n_missing_before = hitter_stats["launch_angle"].isna().sum()
        la_missing_pct_before = (la_n_missing_before / la_n_total_before * 100.0
                                    if la_n_total_before > 0 else 0.0)
        needs_la = (la_n_total_before > 0) and (la_missing_pct_before > 30.0)

    # Persist coverage state to session_state so a diagnostic expander
    # near the bottom of the page can show it. Even when the fill is skipped
    # because coverage is already good, we want to be able to see that.
    st.session_state["_la_missing_pct_before"] = la_missing_pct_before
    st.session_state["_la_n_total"] = la_n_total_before
    st.session_state["_la_fill_ran"] = bool(needs_la)
    st.session_state["_la_fill_error"] = None

    if needs_la:
        # Status placeholder that gets replaced after the fill completes —
        # this is visible IMMEDIATELY so we can confirm the function was
        # actually invoked. If the page shows the spinner and then never
        # the success/error message, an upstream exception killed the script.
        la_status = st.empty()
        la_status.info(f"🔄 Calling LA fill ({la_n_total_before} hitters need processing)...")
        import time as _time
        _t_start = _time.time()
        try:
            from data_fetcher import fill_hitter_la_for_slate
            la_log: list = []
            with st.spinner("Fetching real launch angles from Statcast (bulk first, ~5s)..."):
                hitter_stats = fill_hitter_la_for_slate(hitter_stats, slate, log_steps=la_log)
            elapsed = _time.time() - _t_start
            st.session_state["_la_fill_elapsed_sec"] = round(elapsed, 2)
            st.session_state["_la_fill_steps"] = la_log
            # Re-measure coverage AFTER fill so we can report the delta
            if "launch_angle" in hitter_stats.columns:
                n_missing_after = hitter_stats["launch_angle"].isna().sum()
                n_total_after = len(hitter_stats)
                pct_after = (n_missing_after / n_total_after * 100.0
                                if n_total_after > 0 else 0.0)
                st.session_state["_la_missing_pct_after"] = pct_after
                # Replace the status placeholder with the outcome
                if pct_after < 10:
                    la_status.success(
                        f"✅ LA fill complete: {n_total_after - n_missing_after}/{n_total_after} "
                        f"hitters now have LA ({elapsed:.1f}s)"
                    )
                elif pct_after < 50:
                    la_status.warning(
                        f"⚠️ LA fill partial: {n_total_after - n_missing_after}/{n_total_after} "
                        f"have LA ({pct_after:.0f}% still missing, {elapsed:.1f}s). "
                        f"Enable 'Show data diagnostic' in sidebar for endpoint details."
                    )
                else:
                    la_status.error(
                        f"❌ LA fill failed mostly: only {n_total_after - n_missing_after}/{n_total_after} "
                        f"have LA ({pct_after:.0f}% still missing). "
                        f"Enable 'Show data diagnostic' in sidebar to see endpoint errors."
                    )
            else:
                st.session_state["_la_missing_pct_after"] = 100.0
                la_status.error("❌ LA column missing entirely after fill.")
        except Exception as e:
            st.session_state["_la_fill_error"] = f"{type(e).__name__}: {str(e)[:200]}"
            import traceback as _tb
            st.session_state["_la_fill_traceback"] = _tb.format_exc()[:1500]
            la_status.error(f"❌ LA fill crashed: {type(e).__name__}: {str(e)[:120]}")
    else:
        # Already healthy — record current coverage as the "after" too
        st.session_state["_la_missing_pct_after"] = la_missing_pct_before

# Last-resort: if IP is still completely missing for everyone, estimate from
# Statcast PA so the model has *something* to work with (≈4.3 PA per IP)
if not pitcher_stats.empty:
    if "ip" not in pitcher_stats.columns or pitcher_stats["ip"].isna().all():
        if "pa" in pitcher_stats.columns and pitcher_stats["pa"].notna().any():
            pitcher_stats["ip"] = (pitcher_stats["pa"] / 4.3).round(1)
    # Also if k9 is missing entirely, derive from k_percent
    if "k9" not in pitcher_stats.columns or pitcher_stats["k9"].isna().all():
        if "k_percent" in pitcher_stats.columns and pitcher_stats["k_percent"].notna().any():
            pitcher_stats["k9"] = (pitcher_stats["k_percent"] * 4.3 * 9 / 100).round(2)

# Rookie identification - fetch MLB debut year for all relevant player IDs
# A "rookie" is anyone whose debut year matches the current season.
try:
    from data_fetcher import fetch_player_debut_years
    from datetime import date as _date
    cur_year = _date.today().year
    rookie_ids = set()
    if not pitcher_stats.empty and "player_id" in pitcher_stats.columns:
        pids = tuple(int(x) for x in pitcher_stats["player_id"].dropna().astype(int).tolist())
        if pids:
            debuts = fetch_player_debut_years(pids)
            pitcher_stats["debut_year"] = pitcher_stats["player_id"].map(debuts)
            pitcher_stats["is_rookie"] = pitcher_stats["debut_year"] == cur_year
            rookie_ids.update({pid for pid, yr in debuts.items() if yr == cur_year})
    if not hitter_stats.empty and "player_id" in hitter_stats.columns:
        h_pids = tuple(int(x) for x in hitter_stats["player_id"].dropna().astype(int).tolist())
        if h_pids:
            h_debuts = fetch_player_debut_years(h_pids)
            hitter_stats["debut_year"] = hitter_stats["player_id"].map(h_debuts)
            hitter_stats["is_rookie"] = hitter_stats["debut_year"] == cur_year
            rookie_ids.update({pid for pid, yr in h_debuts.items() if yr == cur_year})
except Exception:
    pass

# Sprint speed
if use_sprint_speed:
    try:
        sprint_df = get_sprint_speed()
        if not sprint_df.empty and "player_id" in sprint_df.columns and "player_id" in hitter_stats.columns:
            sprint_cols = [c for c in ["player_id", "sprint_speed", "hp_to_1b"]
                            if c in sprint_df.columns]
            hitter_stats = hitter_stats.merge(
                sprint_df[sprint_cols], on="player_id", how="left", suffixes=("", "_sp"),
            )
    except Exception:
        pass


