# ----- 🎛️ Custom Grade Builder (moved from mid-script) -----
with st.expander("🎛️ Custom Grade Builder — pick your own metrics", expanded=False):
    st.caption(
        "Build a custom composite by selecting metrics and weights. "
        "Read-only — does not affect pick_score."
    )
    if combined_all is not None and not combined_all.empty:
        st.markdown(
            "Build your own composite grade. Pick the stats you care about and "
            "the model will percentile-rank every hitter across the slate on those "
            "metrics, then composite them. Adjust weights to emphasize what matters "
            "most to you. **Purely exploratory — does not change pick_score.**"
        )

        # Metric catalog — name → (label, lower_is_better, description)
        # Only metrics that actually live on combined_all show up; we filter below.
        _METRIC_CATALOG = {
            # === Power signals ===
            "barrel_pct":             ("Barrel %",                 False, "Overall barrel rate"),
            "pulled_brl_pct":         ("Pulled-air Barrel %",      False, "HR-specific (best single HR predictor)"),
            "iso":                    ("ISO",                      False, "Isolated power (SLG - AVG)"),
            "slg":                    ("SLG",                      False, "Slugging percentage"),
            "hard_hit":               ("Hard Hit %",               False, "% of contact ≥95 mph EV"),
            "avg_ev":                 ("Avg Exit Velocity",        False, "Average exit velocity"),
            "fb_pct":                 ("Fly Ball %",               False, "FB rate (HRs come from FB)"),
            "la":                     ("Launch Angle (avg)",       False, "Average launch angle"),
            "max_hit_speed":          ("Max EV",                   False, "Peak exit velocity (raw power)"),
            # === Predictive composites ===
            "xwoba":                  ("xwOBA",                    False, "Expected wOBA (Statcast)"),
            "xwobacon":               ("xwOBAcon",                 False, "Expected wOBA on contact"),
            "xba":                    ("xBA",                      False, "Expected batting average"),
            "ops":                    ("OPS",                      False, "On-base + slugging"),
            "obp":                    ("OBP",                      False, "On-base percentage"),
            # === Plate discipline ===
            "bb_pct":                 ("BB %",                     False, "Walk rate (higher better)"),
            "k_pct":                  ("K %",                      True,  "Strikeout rate (LOWER better)"),
            "whiff_pct":              ("Whiff %",                  True,  "Whiff rate (LOWER better)"),
            "discipline_score":       ("Discipline Score",         False, "K%/BB% composite (existing)"),
            # === Form / recency ===
            "recent_hr":              ("Recent HRs (14d)",         False, "HRs in last 14 days"),
            "recent_hr_weighted_rate": ("Weighted Recent HR Rate",  False, "Recency-weighted HR/PA"),
            "hr_streak_games":        ("Active HR Streak",         False, "Consecutive games with HR"),
            "hr_form":                ("HR Form Composite",        False, "Multi-stat form (existing)"),
            # === Existing composites ===
            "power_score":            ("Power Score",              False, "Existing power composite"),
            "must_have_met":          ("Must-Have Criteria Met",   False, "How many HR Must-Have thresholds a hitter clears (learning-loop predictive)"),
            "nuclear_met":            ("Nuclear Criteria Met",     False, "How many Nuclear thresholds a hitter clears"),
            "hr_pa_pct":              ("HR per PA %",              False, "Per-plate-appearance HR rate"),
            "xslg":                   ("xSLG",                     False, "Expected slugging (Statcast)"),
            "blast_pct":              ("Blast %",                  False, "Elite-contact blast rate"),
            "matchup_opp":            ("Matchup vs Pitcher",       False, "Hitter advantage vs this pitcher"),
            "hr_game_pct":            ("HR Game %",                False, "Model's HR probability this game"),
            "hit_game_pct":           ("Hit Game %",               False, "Model's hit probability this game"),
            # === Matchup specifics ===
            "pitch_hr_score":         ("Arsenal HR Score",         False, "Per-pitch HR threat"),
            "pitch_match_score":      ("Pitch Match Score",        False, "Per-pitch wOBA composite"),
            "env_boost":              ("Environmental Boost",      False, "Park × weather multiplier"),
            # v43.62: park_hand_factor entry removed — never produced on
            # combined_all (computed per-row in the matchup loop, not merged
            # back). Was filtered out by the "_available" check below anyway,
            # but better to remove dead entries from the catalog.
        }

        # Filter to columns that exist + have data
        _available = {
            k: v for k, v in _METRIC_CATALOG.items()
            if k in combined_all.columns
            and pd.to_numeric(combined_all[k], errors="coerce").notna().any()
        }

        if not _available:
            st.warning("No metrics available — no usable columns in combined_all.")
        else:
            # ============================================================
            # v43.94 (user-reported): three fixes to this tool.
            # 1. PRESETS — you shouldn't need to be a sabermetrician to use
            #    this. Four curated weight sets, incl. a data-driven one
            #    wired to Section G's measured correlations.
            # 2. st.form — previously EVERY slider tick reran the whole
            #    script (the "takes so long to load"). Now nothing
            #    recomputes until you press Apply.
            # 3. Starters-only default + minimum-data rule — bench players
            #    (82-84% coverage) filled the table with "None" cells, and
            #    per-row renormalization let a player with data on ONE
            #    metric outrank complete-data starters. Now a row needs
            #    data on ≥60% of the selected metrics to receive a score,
            #    and a Data column shows n/total so partial rows are
            #    visible instead of silently skewing.
            # ============================================================
            _PRESETS = {
                "🏆 Model blend (recommended start)": {
                    "hr_game_pct": 3.0, "matchup_opp": 1.5, "power_score": 1.5,
                    "pitch_hr_score": 1.0, "recent_hr_weighted_rate": 1.0,
                    "env_boost": 0.75,
                },
                "💪 Raw power (matchup-blind)": {
                    "pulled_brl_pct": 2.0, "barrel_pct": 2.0, "iso": 1.5,
                    "hard_hit": 1.0, "fb_pct": 1.0, "max_hit_speed": 0.75,
                },
                "🎯 Matchup-driven (today-specific)": {
                    "matchup_opp": 2.0, "pitch_hr_score": 2.0,
                    "pitch_match_score": 1.5, "env_boost": 1.0,
                    "hr_game_pct": 1.0,
                },
                # v44.08 (user-built from Section G): the 7 metrics that
                # showed the strongest + most STABLE correlation with actual
                # HRs over the accumulated slates, weighted by reliability
                # (avg_corr / std). barrel_pct + pulled_brl_pct led on
                # stability; avg_ev + iso led on raw correlation.
                "🧪 Pattern-7 (your learning-loop leaders)": {
                    "barrel_pct": 2.0, "pulled_brl_pct": 2.0,
                    "avg_ev": 1.75, "hard_hit": 1.5, "iso": 1.5,
                    "power_score": 1.25, "must_have_met": 1.0,
                },
                # v44.11 — "DINGER SCORE" builder preset shows the SEASON-POWER
                # BASE (avg_ev/barrel/pulled_brl/hard_hit/iso/blast). The
                # per-game Dinger column adds recency/park/matchup context on
                # top; this builder view is the pure power ranking. Sourced
                # from the DINGER_BASE_WEIGHTS constant so they never drift.
                "💥 Dinger Score (season-power base)": dict(DINGER_BASE_WEIGHTS),
            }
            # Data-driven preset from the learning loop (Section G).
            _dd_weights, _dd_note = None, None
            try:
                from backtest import load_pattern_history
                from pattern_analysis import rolling_feature_importance
                _hist = load_pattern_history()
                _imp = rolling_feature_importance(_hist) if _hist else None
                if _imp is not None and not _imp.empty:
                    _top = _imp[_imp["feature"].isin(_available.keys())].head(6)
                    if len(_top) >= 3:
                        _max_c = max(abs(float(r["avg_corr"])) for _, r in _top.iterrows()) or 1.0
                        _dd_weights = {
                            r["feature"]: round(3.0 * abs(float(r["avg_corr"])) / _max_c, 2)
                            for _, r in _top.iterrows()
                        }
                        _dd_note = f"weights ∝ measured HR correlation over {int(_top['n_days'].max())} day(s) of your own slates"
                if _dd_weights:
                    _PRESETS["🤖 Data-driven (learned from YOUR results)"] = _dd_weights
            except Exception:
                pass

            # v44.08: fold the user's SAVED custom metrics in as selectable
            # presets (prefixed 💾) so a formula you built once can be
            # re-applied any day without rebuilding it.
            _saved_metrics = {}
            try:
                from backtest import load_custom_metrics
                _saved_metrics = load_custom_metrics() or {}
                for _sm_name, _sm in _saved_metrics.items():
                    _w = _sm.get("weights") if isinstance(_sm, dict) else None
                    if isinstance(_w, dict) and _w:
                        _PRESETS[f"💾 {_sm_name}"] = _w
            except Exception:
                pass

            _preset_options = list(_PRESETS.keys()) + ["🛠️ Custom — pick your own"]
            with st.form("cgb_form"):
                _preset_choice = st.selectbox(
                    "Weight preset — a sensible starting point so you don't have to guess:",
                    options=_preset_options, index=0,
                    help=(
                        "Model blend mirrors pick_score's philosophy. Raw power "
                        "ranks pure thump ignoring today's pitcher. Matchup-driven "
                        "is the opposite. Data-driven (appears after ~3 days of "
                        "results) weights features by their MEASURED correlation "
                        "with actual HRs on your slates — the learning loop's "
                        "answer to 'what should the weights be'."
                    ),
                )
                _starters_only_cgb = st.checkbox(
                    "Starters only (recommended)", value=True,
                    help=(
                        "Bench players have 82-84% data coverage vs 100% for "
                        "starters — including them fills the table with blank "
                        "cells and lets partial-data players skew the rankings."
                    ),
                )
                _label_to_key = {f"{v[0]} — {v[2]}": k for k, v in _available.items()}
                _selected_labels = st.multiselect(
                    "Custom mode only — pick metrics (ignored when a preset is chosen):",
                    options=list(_label_to_key.keys()), default=[],
                )
                _custom_weights_on = st.checkbox(
                    "Custom mode: adjust weights after first Apply", value=False,
                )
                _cgb_go = st.form_submit_button("▶ Apply / Recompute")
            if not _cgb_go and "cgb_ran_once" not in st.session_state:
                st.info("Choose a preset (or Custom) and press **Apply**. Nothing recomputes until you do — that's what makes this fast now.")
                _selected_keys = []
            else:
                st.session_state["cgb_ran_once"] = True
                if _preset_choice != "🛠️ Custom — pick your own":
                    _preset_w = _PRESETS[_preset_choice]
                    _selected_keys = [k for k in _preset_w if k in _available]
                    _weights = {k: _preset_w[k] for k in _selected_keys}
                    _w_desc = " · ".join(f"{_available[k][0]} ×{_weights[k]}" for k in _selected_keys)
                    st.caption(f"**Using preset:** {_w_desc}" + (f" — _{_dd_note}_" if (_dd_note and _preset_choice.startswith('🤖')) else ""))
                else:
                    _selected_keys = [_label_to_key[lbl] for lbl in _selected_labels]
                    _weights = {k: 1.0 for k in _selected_keys}
                    if _custom_weights_on and _selected_keys:
                        cols = st.columns(min(4, len(_selected_keys)))
                        for i, k in enumerate(_selected_keys):
                            with cols[i % len(cols)]:
                                _weights[k] = st.slider(
                                    f"{_available[k][0]} weight",
                                    min_value=0.0, max_value=3.0, value=1.0, step=0.25,
                                    key=f"cgb_w_{k}",
                                )

            if not _selected_keys:
                pass
            else:

                # ====================================================
                # COMPUTE CUSTOM COMPOSITE
                # ====================================================
                # For each metric: numeric → percentile-rank (NaN preserved)
                # → invert if lower_is_better → multiply by user weight
                # → sum per row, normalize by total weight from contributing
                # (non-NaN) metrics for that row.
                # v43.94: starters-only frame (bench coverage gaps were the
                # "None in a lot of categories" complaint) + percentiles are
                # now ranked WITHIN this frame so bench NaNs can't distort
                # starter ranks either.
                _cgb_frame = combined_all
                if _starters_only_cgb and "is_bench" in combined_all.columns:
                    _cgb_frame = combined_all[
                        ~combined_all["is_bench"].fillna(False).astype(bool)
                    ]
                _custom_sum = pd.Series(0.0, index=_cgb_frame.index)
                _weight_total = pd.Series(0.0, index=_cgb_frame.index)
                _n_present = pd.Series(0, index=_cgb_frame.index)

                for k in _selected_keys:
                    col = pd.to_numeric(_cgb_frame[k], errors="coerce")
                    if col.isna().all():
                        continue
                    pct = col.rank(pct=True, na_option="keep") * 100
                    lower_better = _available[k][1]
                    if lower_better:
                        pct = 100 - pct
                    w = float(_weights.get(k, 1.0))
                    mask = pct.notna()
                    _custom_sum = _custom_sum.add((pct.fillna(0) * w), fill_value=0)
                    _weight_total = _weight_total + (mask.astype(float) * w)
                    _n_present = _n_present + mask.astype(int)

                _custom_score = (_custom_sum / _weight_total.replace(0, np.nan))
                # v43.94 minimum-data rule: a row must have data on ≥60% of
                # the selected metrics to receive a score. Without this, a
                # player with ONE lucky percentile and NaN everywhere else
                # outranked complete-data hitters — the exact skew reported.
                _min_needed = max(1, int(np.ceil(0.6 * len(_selected_keys))))
                _custom_score = _custom_score.where(_n_present >= _min_needed)

                # ====================================================
                # GRADE FROM PERCENTILE COMPOSITE
                # ====================================================
                def _custom_grade(s):
                    if pd.isna(s):
                        return "—"
                    if s >= 90: return "A+"
                    if s >= 80: return "A"
                    if s >= 70: return "B+"
                    if s >= 55: return "B"
                    if s >= 40: return "C+"
                    if s >= 25: return "C"
                    if s >= 10: return "D"
                    return "F"

                def _custom_emoji(s):
                    if pd.isna(s):
                        return "⚪"
                    if s >= 80: return "🟢"
                    if s >= 55: return "🟡"
                    if s >= 25: return "🟠"
                    return "🔴"

                # ====================================================
                # DISPLAY
                # ====================================================
                _has_score = _custom_score.notna()
                if not _has_score.any():
                    st.warning(
                        f"No hitters have data on ≥{_min_needed} of the "
                        f"{len(_selected_keys)} selected metrics."
                    )
                else:
                    _n_excluded = int((_n_present > 0).sum() - _has_score.sum())
                    if _n_excluded > 0:
                        st.caption(
                            f"ℹ️ {_n_excluded} hitter(s) hidden for having data on "
                            f"fewer than {_min_needed}/{len(_selected_keys)} selected "
                            f"metrics — partial-data rows skew rankings."
                        )
                    _id_cols = [c for c in ("player_name", "team", "opp_pitcher")
                                if c in _cgb_frame.columns]
                    _display = _cgb_frame.loc[_has_score, _id_cols + _selected_keys].copy()
                    _display["data_n"] = _n_present[_has_score].astype(int).astype(str) + f"/{len(_selected_keys)}"
                    _display["custom_signal"] = _custom_score[_has_score].apply(_custom_emoji)
                    _display["custom_grade"] = _custom_score[_has_score].apply(_custom_grade)
                    _display["custom_score"] = _custom_score[_has_score].round(1)
                    _front = ["custom_signal", "custom_grade", "custom_score", "data_n"]
                    _display = _display[_front + [c for c in _display.columns if c not in _front]]
                    _display = _display.sort_values(
                        "custom_score", ascending=False, na_position="last",
                    ).head(30)

                    st.dataframe(
                        _display, hide_index=True, use_container_width=True,
                        column_config={
                            "custom_signal": st.column_config.TextColumn("Sig", width="small"),
                            "custom_grade":  st.column_config.TextColumn("Grade", width="small"),
                            "custom_score":  st.column_config.NumberColumn(
                                "Score (percentile)", format="%.1f",
                                help="Weighted average of percentile ranks across selected metrics (0-100)",
                            ),
                            "data_n": st.column_config.TextColumn(
                                "Data", width="small",
                                help="Metrics with data for this hitter / metrics selected. Rows below the 60% floor are hidden.",
                            ),
                            "player_name":   _player_col("Hitter"),
                            "team":          st.column_config.TextColumn("Team", width="small"),
                            "opp_pitcher":   st.column_config.TextColumn("vs Pitcher"),
                        },
                    )
                    n_qualified = int(_has_score.sum())
                    weight_str = " (custom weights)" if _custom_weights_on else " (preset/equal weight)"
                    st.caption(
                        f"Top 30 of {n_qualified} hitters with data on at least one "
                        f"selected metric. Composite of {len(_selected_keys)} metric"
                        f"{'s' if len(_selected_keys) != 1 else ''}{weight_str}. "
                        f"Grades: A+ ≥90 / A ≥80 / B+ ≥70 / B ≥55 / C+ ≥40 / C ≥25 / "
                        f"D ≥10 / F <10 (percentile composite)."
                    )

                    # v44.08 (user-requested): save THIS formula as a named
                    # custom metric so it persists and can be re-applied any
                    # day from the preset dropdown (prefixed 💾). Stores the
                    # {metric: weight} set that produced the table above.
                    with st.expander("💾 Save this as a named custom metric", expanded=False):
                        st.caption(
                            "Give this weight formula a name to save it. It'll "
                            "appear in the preset dropdown (💾 prefix) on future "
                            "visits, so you can re-run it without rebuilding — and "
                            "track how it does over time in the results."
                        )
                        with st.form("cgb_save_form"):
                            _save_name = st.text_input(
                                "Metric name", value="",
                                placeholder="e.g. My Power Blend",
                                max_chars=60,
                            )
                            _save_go = st.form_submit_button("💾 Save formula")
                        if _save_go:
                            if not _save_name.strip():
                                st.warning("Give it a name first.")
                            else:
                                try:
                                    from backtest import save_custom_metric
                                    _formula = {k: float(_weights.get(k, 1.0))
                                                for k in _selected_keys}
                                    if save_custom_metric(_save_name.strip(), _formula):
                                        st.success(
                                            f"Saved **{_save_name.strip()}** — "
                                            f"pick it from the preset dropdown next time."
                                        )
                                    else:
                                        st.error("Save failed (storage unavailable this session).")
                                except Exception as _se:
                                    st.error(f"Save error: {type(_se).__name__}")

                        # Delete controls for existing saved metrics
                        if _saved_metrics:
                            _del = st.selectbox(
                                "Delete a saved metric",
                                options=["(none)"] + list(_saved_metrics.keys()),
                                index=0, key="cgb_del_select",
                            )
                            if _del != "(none)" and st.button(f"🗑️ Delete '{_del}'", key="cgb_del_btn"):
                                try:
                                    from backtest import delete_custom_metric
                                    if delete_custom_metric(_del):
                                        st.success(f"Deleted {_del}. Reload to refresh the dropdown.")
                                except Exception:
                                    st.error("Delete failed.")
    else:
        st.caption("No slate data loaded yet.")


# ----- 🆘 Admin & Recovery (owner-only: destructive emergency tools) -----
# v44.41: contains a gist-reset that permanently wipes all history. Must never
# be reachable by a non-owner. Gate the entire block.
if owner_mode:
  with st.expander("🆘 Admin & Recovery — emergency tools", expanded=False):
    st.caption(
        "Use these only when the normal flow is broken. "
        "Emergency gist reset wipes all backtest history — last resort."
    )
    # v43.48: emergency gist reset — when gist content is corrupt (invalid
    # JSON from truncation/manual edit), reads fail forever and saves stop.
    # The two-click confirm prevents accidental wipes; the button only fires
    # when the user has actively been warned about a read failure.
    try:
        from backtest import emergency_reset_gist, durable_storage_configured
        if durable_storage_configured():
            with st.expander("🆘 Emergency: reset gist storage", expanded=False):
                st.caption(
                    "Use this ONLY if gist saves are failing with an "
                    "'invalid JSON' / 'Expecting :' error. Resets the "
                    "gist back to `{}` — **all prior snapshot history will "
                    "be permanently lost.** v43.48's size pruning should "
                    "prevent the corruption from recurring."
                )
                confirm_reset = st.checkbox(
                    "I understand this WIPES all backtest history",
                    key="gist_reset_confirm",
                )
                if confirm_reset and st.button(
                    "🆘 Reset gist to empty {}",
                    key="gist_reset_button",
                ):
                    ok, msg = emergency_reset_gist()
                    if ok:
                        st.success(f"✅ {msg}")
                    else:
                        st.error(f"❌ {msg}")
    except Exception:
        pass
st.caption(
    f"Built {datetime.now().strftime('%Y-%m-%d %H:%M')} · "
    f"Sources: MLB Stats API, Baseball Savant, Open-Meteo · "
    f"LaunchCast"
)
